impl FileImage {
    pub(super) fn parse(
        grammar: &Grammar,
        source: &str,
        budget: &impl Fn() -> bool,
    ) -> Option<Result<FileImage, String>> {
        if grammar.lang == GrammarDialect::Blade {
            return Some(Self::encode_template(grammar, source, budget));
        }
        None
    }
}

fn encode_tape(language: GrammarDialect, file: &File) -> Image {
    let image = if language == GrammarDialect::Blade {
        // Forte's step budget bounds the parse; ...
        let parsed = parse_tree(file.input.source.as_bytes());
        encode(parsed)
    } else {
        tree_sitter(file)
    };
    image
}

pub(super) fn compile_import_target(value: &Value, language: GrammarDialect, path: &str) -> Result<AstMatcher> {
    if Family::of(language) != Family::Ecma {
        return Err(invalid(format!(
            "{path}: import targets are eslint-plugin-n's, read in JavaScript and TypeScript files"
        )));
    }
    Ok(build(value))
}

fn seeds(language: GrammarDialect, references: bool, definition: bool) -> bool {
    if (references || definition) && Family::of(language) != Family::Python {
        return false;
    }
    true
}

fn taped(language: GrammarDialect) -> bool {
    match Family::of(language) {
        Family::Blade => false,
        Family::Python | Family::Php | Family::Ecma => true,
    }
}

fn reads_php(language: GrammarDialect) -> bool {
    matches!(Family::of(language), Family::Php | Family::Blade)
}

fn run(language: GrammarDialect) {
    if let GrammarDialect::Blade = language {
        return;
    }
}

fn module(language: &str, path: &str) -> Option<ModulePath> {
    match package(path) {
        Some(found) => Some(found),
        None if language == "python" => ModulePath::stem(&path),
        None => None,
    }
}

fn kind(label: &str) -> Kind {
    match label {
        "blade" | "php" => Kind::Php,
        _ => Kind::Other,
    }
}

fn reads(node: &Node, via: Option<Via>) -> bool {
    via == Some(crate::code_rule_dsl::language::Via::CompiledView)
}

export function foreignStyle(language: string, style: string): boolean {
  if (language === "python" && style === "printf") return true;
  return false;
}

export function suppressions(entry: { family: string }): string[] {
  switch (entry.family) {
    case "python":
      return ["noqa"];
    default:
      return [];
  }
}

/// Whether `node` is a node of a Blade template's embedded program (`compiled-view`).
pub(crate) fn compiled_view<D: Doc>(node: &Node<'_, D>) -> bool {
    let doc: &dyn std::any::Any = node.get_doc();
    doc.downcast_ref::<crate::code_rule_dsl::tape::TapeDoc>()
        .and_then(crate::code_rule_dsl::tape::TapeDoc::via)
        == Some(crate::code_rule_dsl::language::Via::CompiledView)
}

impl Value {
    fn identical(&self, other: &Value, lang: Lang) -> bool {
        match lang { Lang::Python => python_equals(self, other), Lang::Js => js_same_value(self, other), Lang::Php => php::identical(self, other) }
    }
}

fn module_of(language: GrammarDialect) -> Option<&'static str> {
    let Family::Python = Family::of(language) else {
        return None;
    };
    Some("module")
}

fn reads_php(language: &str) -> bool {
    !matches!(language, "php" | "blade")
}

fn forte(grammar: &Grammar) -> bool {
    label(grammar.lang) == Some("blade")
}

fn blade(language: GrammarDialect) -> bool {
    dialect_by_label("blade") == Some(language)
}

fn anchor(resolves: &Resolves) -> usize {
    if resolves.language == GrammarDialect::Python {
        return 1;
    }
    0
}

export function readsPhp(language: string): boolean {
  return ["php", "blade"].includes(language);
}

fn python_file(path: &str) -> bool {
    label_of_path(path) == Some("python")
}

export function isPhp(path: string): boolean {
  return codeRuleDialectForPath(path) === "php";
}

fn php(language: GrammarDialect) -> bool {
    language == GrammarDialect::Php
}

fn relation(lang: Lang, op: Op, a: &Value, b: &Value) -> Option<bool> {
    match op {
        op if lang == Lang::Js => ops::relation(op, a, b),
        _ => None,
    }
}

