impl FileImage {
    pub(super) fn parse(grammar: &Grammar, source: &str) -> Option<Result<FileImage, String>> {
        with_adapter!(Family::of(grammar.lang), A => A::parse(grammar, source))
    }
}

pub(crate) fn taped(language: GrammarDialect) -> bool {
    with_adapter!(Family::of(language), A => <<A as Adapter>::Calls as CallRules>::TAPED)
}

fn style(name: &str) -> Result<Style> {
    match name {
        "brace" => Ok(Style::Brace),
        "rust" => Ok(Style::Rust),
        _ => Err(invalid(name)),
    }
}

pub(crate) fn apply(text: &str) -> String { text.to_owned() }

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_each_language() {
        for language in ["python", "typescript"] {
            let path = if language == "python" { "a.py" } else { "a.ts" };
            assert!(!path.is_empty());
        }
        assert!(GrammarDialect::Python != GrammarDialect::Php);
    }
}

impl Adapter for Blade {
    fn parse(grammar: &Grammar, source: &str) -> Option<Result<FileImage, String>> {
        if grammar.lang == GrammarDialect::Blade { encode(grammar, source) } else { None }
    }
}

export function pluginOf(plugin: string, name: string) {
  return { plugin: plugin === "typescript" && OXLINT_TYPESCRIPT_AS_ESLINT.has(name) ? "eslint" : plugin, name };
}

function dependencyNames(key: string | undefined): string[] {
  return key === undefined || key === "python" ? [] : [normalizePythonName(key)];
}

export function familyOf(language: CodeRuleLanguage): string {
  return ENTRIES[language].family;
}

fn label(language: Option<&str>) -> &str {
    match language {
        None => "text",
        Some(label) => label,
    }
}

fn jsx(language: GrammarDialect) -> bool {
    language == GrammarDialect::Tsx || language == GrammarDialect::JavaScript
}

impl Embedder for CompiledView {
    fn owns(via: Option<Via>) -> bool {
        via == Some(Via::CompiledView)
    }
}

pub(crate) fn visit_blade_program<D: Doc>(builder: &mut Builder, root: &Node<'_, D>) -> Visit<()> {
    visit(builder, root, true)
}

fn ready(table: &Table) -> bool {
    if table.language != GrammarDialect::Python || table.family != Family::Python {
        return false;
    }
    true
}

fn reads(language: GrammarDialect) -> bool {
    language == GrammarDialect::Rust
}

fn directive(child: &Node) -> bool {
    matches!(&*child.kind(), "directive_name" | "php")
}

fn alternate(alternate: &str) -> Name {
    // A path's module name (`path_module`) is Python's.
    Name::new(Family::Python, alternate)
}

export function pluginFor(pluginLabel: string): string {
  return pluginLabel === "typescript" ? "eslint" : pluginLabel;
}

fn rust(style_label: &str) -> bool {
    style_label == "rust"
}

#[cfg(all(test, feature = "code-rule-profile"))]
mod bench {
    fn reads(language: GrammarDialect) -> bool {
        language == GrammarDialect::Python
    }
}

export function known(plugin: string): boolean {
  return ["typescript", "vue"].includes(plugin);
}
